"""Generate the supported editor action index from the actual dispatch tables."""

from pathlib import Path

from defjam_caf.editor import Editor
from defjam_caf.retail import Session


def render():
    lines = [
        "# Editor actions",
        "",
        "Generated by `python scripts/editor_actions.py` from the Python dispatch tables.",
        "Requests carry `id`, `action`, and an `args` object. Native file pickers use",
        "`choose_*` bridge actions before submitting these editor actions.",
        "",
        "| Action | Handler |",
        "| --- | --- |",
    ]
    for name, handler in sorted(Editor.ACTIONS.items()):
        if name != "retail_*":
            lines.append(f"| `{name}` | `Editor.{handler.__name__}` |")
    for name, handler in sorted(Session.ACTIONS.items()):
        lines.append(f"| `retail_{name}` | `Session.{handler.__name__}` |")
    return "\n".join(lines) + "\n"


if __name__ == "__main__":
    target = Path(__file__).resolve().parents[1] / "docs/editor-actions.md"
    target.write_text(render(), encoding="utf-8")
